-- Source: FED_CMS_MEDICARE_PHYSICIAN_OTHER_PRACTITIONERS_BY_PROVIDER (1,296,739 rows)  [row count re-verified against the live table 2026-08-11; header had said 500000]
-- Generated by scripts/gen_mart_models.py
--
-- This is the reliable total: one row per NPI, not_null + unique, no row is
-- ever deleted for low volume. DRUG_SPRSN_IND / MED_SPRSN_IND only blank out
-- the drug-vs-medical SPLIT of that provider's totals when a slice would show
-- under 11 beneficiaries; the provider's grand total (tot_benes/tot_srvcs/etc.)
-- still stands. Contrast: health__fed_cms_medicare_physician_other_practitioners_by_provider_and_servi
-- (same source family, one row per NPI x HCPCS x place of service) DELETES
-- whole rows under that same 11-beneficiary line, so it undercounts a
-- provider's true volume badly (90.2% of one sampled provider's billing was
-- gone at that grain). Use this table for a provider's real total.
-- Fixed 2026-09-20: 48 bare try_to_number()/try_to_double() casts -- a landmine,
-- not an active bug today (live-checked: 0 of 1,296,739 rows round on any of the
-- 14 BENE_* count columns; 0 literal 'nan' anywhere). Stayed on source() instead
-- of the stg_fed_cms_medicare_physician_other_practitioners_by_provider__providers
-- staging model that exists for this same table: that model's generator marks
-- BENE_AVG_AGE and all 25 BENE_CC_*_PCT comorbidity-rate columns "integer" --
-- true of this table's data today (100% whole numbers, live-checked on
-- BENE_AVG_AGE and BENE_CC_BH_TOBACCO_V1_PCT) but an age average and a
-- comorbidity RATE are continuous measures, not counts, same reasoning Chris
-- already ruled on for finance__fed_fec_committee_to_candidate's dollar amount:
-- stg_int would silently NULL a future decimal load instead of keeping it.
-- Wrapped the casts in place instead: try_to_number -> stg_int for the 14
-- whole-number BENE_* counts, try_to_double -> stg_float for the 9 dollar
-- amounts and the 25 BENE_CC_*_PCT rates.

with source as (
    select * from {{ source('ripple_raw', 'FED_CMS_MEDICARE_PHYSICIAN_OTHER_PRACTITIONERS_BY_PROVIDER') }}
)

select
    RNDRNG_NPI as rndrng_npi,
    RNDRNG_PRVDR_LAST_ORG_NAME as rndrng_prvdr_last_org_name,
    RNDRNG_PRVDR_FIRST_NAME as rndrng_prvdr_first_name,
    RNDRNG_PRVDR_MI as rndrng_prvdr_mi,
    RNDRNG_PRVDR_CRDNTLS as rndrng_prvdr_crdntls,
    RNDRNG_PRVDR_ENT_CD as rndrng_prvdr_ent_cd,
    RNDRNG_PRVDR_ST1 as rndrng_prvdr_st1,
    RNDRNG_PRVDR_ST2 as rndrng_prvdr_st2,
    RNDRNG_PRVDR_CITY as rndrng_prvdr_city,
    RNDRNG_PRVDR_STATE_ABRVTN as rndrng_prvdr_state_abrvtn,
    RNDRNG_PRVDR_STATE_FIPS as rndrng_prvdr_state_fips,
    RNDRNG_PRVDR_ZIP5 as rndrng_prvdr_zip5,
    RNDRNG_PRVDR_RUCA as rndrng_prvdr_ruca,
    RNDRNG_PRVDR_RUCA_DESC as rndrng_prvdr_ruca_desc,
    nullif(trim(RNDRNG_PRVDR_CNTRY), '') as rndrng_prvdr_cntry,
    RNDRNG_PRVDR_TYPE as rndrng_prvdr_type,
    RNDRNG_PRVDR_MDCR_PRTCPTG_IND as rndrng_prvdr_mdcr_prtcptg_ind,
    TOT_HCPCS_CDS as tot_hcpcs_cds,
    TOT_BENES as tot_benes,
    TOT_SRVCS as tot_srvcs,
    TOT_SBMTD_CHRG as tot_sbmtd_chrg,
    {{ stg_float('TOT_MDCR_ALOWD_AMT') }} as tot_mdcr_alowd_amt,
    {{ stg_float('TOT_MDCR_PYMT_AMT') }} as tot_mdcr_pymt_amt,
    {{ stg_float('TOT_MDCR_STDZD_AMT') }} as tot_mdcr_stdzd_amt,
    DRUG_SPRSN_IND as drug_sprsn_ind,
    DRUG_TOT_HCPCS_CDS as drug_tot_hcpcs_cds,
    DRUG_TOT_BENES as drug_tot_benes,
    DRUG_TOT_SRVCS as drug_tot_srvcs,
    DRUG_SBMTD_CHRG as drug_sbmtd_chrg,
    {{ stg_float('DRUG_MDCR_ALOWD_AMT') }} as drug_mdcr_alowd_amt,
    {{ stg_float('DRUG_MDCR_PYMT_AMT') }} as drug_mdcr_pymt_amt,
    {{ stg_float('DRUG_MDCR_STDZD_AMT') }} as drug_mdcr_stdzd_amt,
    MED_SPRSN_IND as med_sprsn_ind,
    MED_TOT_HCPCS_CDS as med_tot_hcpcs_cds,
    MED_TOT_BENES as med_tot_benes,
    MED_TOT_SRVCS as med_tot_srvcs,
    MED_SBMTD_CHRG as med_sbmtd_chrg,
    {{ stg_float('MED_MDCR_ALOWD_AMT') }} as med_mdcr_alowd_amt,
    {{ stg_float('MED_MDCR_PYMT_AMT') }} as med_mdcr_pymt_amt,
    {{ stg_float('MED_MDCR_STDZD_AMT') }} as med_mdcr_stdzd_amt,
    {{ ripple_num('BENE_AVG_AGE') }} as bene_avg_age,
    {{ stg_int('BENE_AGE_LT_65_CNT') }} as bene_age_lt_65_cnt,
    {{ stg_int('BENE_AGE_65_74_CNT') }} as bene_age_65_74_cnt,
    {{ stg_int('BENE_AGE_75_84_CNT') }} as bene_age_75_84_cnt,
    {{ stg_int('BENE_AGE_GT_84_CNT') }} as bene_age_gt_84_cnt,
    {{ stg_int('BENE_FEML_CNT') }} as bene_feml_cnt,
    {{ stg_int('BENE_MALE_CNT') }} as bene_male_cnt,
    {{ stg_int('BENE_RACE_WHT_CNT') }} as bene_race_wht_cnt,
    {{ stg_int('BENE_RACE_BLACK_CNT') }} as bene_race_black_cnt,
    {{ stg_int('BENE_RACE_API_CNT') }} as bene_race_api_cnt,
    {{ stg_int('BENE_RACE_HSPNC_CNT') }} as bene_race_hspnc_cnt,
    {{ stg_int('BENE_RACE_NATIND_CNT') }} as bene_race_natind_cnt,
    {{ stg_int('BENE_RACE_OTHR_CNT') }} as bene_race_othr_cnt,
    {{ stg_int('BENE_DUAL_CNT') }} as bene_dual_cnt,
    {{ stg_int('BENE_NDUAL_CNT') }} as bene_ndual_cnt,
    {{ stg_float('BENE_CC_BH_ADHD_OTHCD_V1_PCT') }} as bene_cc_bh_adhd_othcd_v1_pct,
    {{ stg_float('BENE_CC_BH_ALCOHOL_DRUG_V1_PCT') }} as bene_cc_bh_alcohol_drug_v1_pct,
    {{ stg_float('BENE_CC_BH_TOBACCO_V1_PCT') }} as bene_cc_bh_tobacco_v1_pct,
    {{ stg_float('BENE_CC_BH_ALZ_NONALZDEM_V2_PCT') }} as bene_cc_bh_alz_nonalzdem_v2_pct,
    {{ stg_float('BENE_CC_BH_ANXIETY_V1_PCT') }} as bene_cc_bh_anxiety_v1_pct,
    {{ stg_float('BENE_CC_BH_BIPOLAR_V1_PCT') }} as bene_cc_bh_bipolar_v1_pct,
    {{ stg_float('BENE_CC_BH_MOOD_V2_PCT') }} as bene_cc_bh_mood_v2_pct,
    {{ stg_float('BENE_CC_BH_DEPRESS_V1_PCT') }} as bene_cc_bh_depress_v1_pct,
    {{ stg_float('BENE_CC_BH_PD_V1_PCT') }} as bene_cc_bh_pd_v1_pct,
    {{ stg_float('BENE_CC_BH_PTSD_V1_PCT') }} as bene_cc_bh_ptsd_v1_pct,
    {{ stg_float('BENE_CC_BH_SCHIZO_OTHPSY_V1_PCT') }} as bene_cc_bh_schizo_othpsy_v1_pct,
    {{ stg_float('BENE_CC_PH_ASTHMA_V2_PCT') }} as bene_cc_ph_asthma_v2_pct,
    {{ stg_float('BENE_CC_PH_AFIB_V2_PCT') }} as bene_cc_ph_afib_v2_pct,
    {{ stg_float('BENE_CC_PH_CANCER6_V2_PCT') }} as bene_cc_ph_cancer6_v2_pct,
    {{ stg_float('BENE_CC_PH_CKD_V2_PCT') }} as bene_cc_ph_ckd_v2_pct,
    {{ stg_float('BENE_CC_PH_COPD_V2_PCT') }} as bene_cc_ph_copd_v2_pct,
    {{ stg_float('BENE_CC_PH_DIABETES_V2_PCT') }} as bene_cc_ph_diabetes_v2_pct,
    {{ stg_float('BENE_CC_PH_HF_NONIHD_V2_PCT') }} as bene_cc_ph_hf_nonihd_v2_pct,
    {{ stg_float('BENE_CC_PH_HYPERLIPIDEMIA_V2_PCT') }} as bene_cc_ph_hyperlipidemia_v2_pct,
    {{ stg_float('BENE_CC_PH_HYPERTENSION_V2_PCT') }} as bene_cc_ph_hypertension_v2_pct,
    {{ stg_float('BENE_CC_PH_ISCHEMICHEART_V2_PCT') }} as bene_cc_ph_ischemicheart_v2_pct,
    {{ stg_float('BENE_CC_PH_OSTEOPOROSIS_V2_PCT') }} as bene_cc_ph_osteoporosis_v2_pct,
    {{ stg_float('BENE_CC_PH_PARKINSON_V2_PCT') }} as bene_cc_ph_parkinson_v2_pct,
    {{ stg_float('BENE_CC_PH_ARTHRITIS_V2_PCT') }} as bene_cc_ph_arthritis_v2_pct,
    {{ stg_float('BENE_CC_PH_STROKE_TIA_V2_PCT') }} as bene_cc_ph_stroke_tia_v2_pct,
    {{ ripple_num('BENE_AVG_RISK_SCRE') }} as bene_avg_risk_scre
